def make_q(base, prompt, options, answer, explanation, strategy, steps):
    q = json.loads(json.dumps(base))
    q.update({"prompt": prompt, "options": [{"id": k, "text": v} for k, v in options], "answer": {"value": answer, "explanation": explanation + f" 正確答案：{answer}"}, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps, "reviewStatus": "draft", "updatedAt": "2026-09-21"})
    q["provenance"]["sourceUrl"] = refs()[0]["url"]
    q["provenance"]["sourceLocator"] = "公立學校公開英文評量的基本句型與語境判讀模式；本題只改寫能力、資料型態與推理層次。"
    q["provenance"]["authoringNote"] = "依官方課綱、本單元 KG 與三所公立學校公開英文評量模式獨立改寫；題幹、選項、答案、解析與互動任務均未複製來源。"
    return q


